def solve_demo(inp, color):
    h,w=len(inp),len(inp[0])
    cells=[(i,j) for i in range(h) for j in range(w) if inp[i][j]==color]
    r0=min(i for i,_ in cells); c0=min(j for _,j in cells)
    pat={(i-r0,j-c0) for i,j in cells}
    ph=max(i for i,_ in pat)+1; pw=max(j for _,j in pat)+1
    res=[row[:] for row in inp]
    out_cells=set()
    for i in range(h-ph+1):
        for j in range(w-pw+1):
            if all(inp[i+di][j+dj]==0 for di,dj in pat):
                out_cells|={(i+di,j+dj) for di,dj in pat}
    for i,j in out_cells: res[i][j]=color
    return res

