lib='''from collections import Counter


def background(grid):
    """The most common cell value in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def accent(grid):
    """The single non-background, non-zero color of the grid."""
    bg = background(grid)
    return [v for v in {v for row in grid for v in row} if v not in (0, bg)][0]

def pattern_cells(grid, color):
    """Positions of all cells of the given color, as a set."""
    return {(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == color}

def normalize(cells):
    """Shift a set of positions so its top-left bounding corner is (0, 0)."""
    r0 = min(i for i, _ in cells); c0 = min(j for _, j in cells)
    return {(i - r0, j - c0) for i, j in cells}

def bounding_size(cells):
    """(height, width) of the bounding box of a set of positions."""
    return max(i for i, _ in cells) + 1, max(j for _, j in cells) + 1

def find_pattern(grid, pat):
    """All top-left positions where the pattern's cells all lie on zeros of the grid."""
    h, w = len(grid), len(grid[0])
    ph, pw = bounding_size(pat)
    return [(i, j) for i in range(h - ph + 1) for j in range(w - pw + 1)
            if all(grid[i + di][j + dj] == 0 for di, dj in pat)]

def stamp(grid, cells, color):
    """A copy of the grid with the given positions recolored."""
    g = [row[:] for row in grid]
    for i, j in cells:
        g[i][j] = color
    return g

def recolor_hidden_copies(grid, color=None):
    """Recolor to color every all-zero occurrence of the grid's colored shape."""
    if color is None:
        color = accent(grid)
    pat = normalize(pattern_cells(grid, color))
    hits = set()
    for i, j in find_pattern(grid, pat):
        hits |= {(i + di, j + dj) for di, dj in pat}
    return stamp(grid, hits, color)
